132	/** invoice id -> amount this payment put on it (only invoices that got a row). */
133	async function fillOf(paymentId: string, lease: TxLease): Promise<Record<string, number>> {
134	  const names = new Map(lease.invoices.map((i) => [i.id, i.kind === "deposit" ? "deposit" : `p${i.periodIndex}`]));
