140	/** R27: paidSen per invoice = sum of its allocations (0 when none). */
141	async function paidSen(lease: TxLease): Promise<number[]> {
142	  const { rows } = await c.query<{ invoice_id: string; paid: number }>(
143	    "select invoice_id, sum(amount_sen)::bigint as paid from public.payment_allocations where lease_id = $1 group by invoice_id",
144	    [lease.id],
145	  );
146	  const m = new Map(rows.map((r) => [r.invoice_id, r.paid]));
147	  return lease.invoices.map((i) => m.get(i.id) ?? 0);
148	}
