155	/** Invariants that must hold after every step: no invoice over-allocated, no 0/negative row,
156	 *  every approved payment = its allocations + unapplied_sen, a non-approved payment has none. */
157	async function assertInvariants(lease: TxLease) {
158	  const paid = await paidSen(lease);
159	  lease.invoices.forEach((inv, k) => expect(paid[k], `invoice ${inv.kind}/${inv.periodIndex}`).toBeLessThanOrEqual(inv.amountSen));
160	  const { rows } = await c.query<{ id: string; status: string; method: string; amount_sen: number; unapplied_sen: number; allocated: number; min_row: number | null }>(
161	    `select p.id, p.status, p.method, p.amount_sen, p.unapplied_sen,
162	            coalesce(sum(a.amount_sen), 0)::bigint as allocated, min(a.amount_sen) as min_row
163	       from public.payments p left join public.payment_allocations a on a.payment_id = p.id
164	      where p.lease_id = $1 group by p.id`,
165	    [lease.id],
166	  );
167	  for (const p of rows) {
168	    if (p.min_row !== null) expect(p.min_row).toBeGreaterThan(0);
169	    if (p.status === "approved") {
170	      expect(p.allocated + p.unapplied_sen).toBe(p.amount_sen);
171	      if (p.method !== "online") expect(p.unapplied_sen).toBe(0);
172	    } else {
173	      expect(p.allocated).toBe(0);
174	    }
175	  }
176	}
