178	/** Runs fn inside a savepoint, expecting it to fail with `code`, and leaves the transaction usable. */
179	async function expectSqlError(fn: () => Promise<unknown>, code: string) {
180	  await c.query("savepoint expect_err");
181	  let err: unknown;
182	  try {
183	    await fn();
184	  } catch (e) {
185	    err = e;
186	  }
187	  await c.query("rollback to savepoint expect_err");
188	  expect(err, `expected SQLSTATE ${code}`).toMatchObject({ code });
189	}
