51	/** Lease + exactly generateSchedule(lease) inside the open transaction. rentFirst inserts the deposit
52	 *  last, so a correct order can never come from insertion order. Returned invoices are in schedule order. */
53	async function insertLeaseTx(lease: LeaseInput, rentFirst = false): Promise<TxLease> {
54	  const schedule = generateSchedule(lease);
55	  const { rows } = await c.query<{ id: string }>(
56	    `insert into public.leases (org_id, unit_id, tenant_id, start_date, end_date, monthly_rent_sen, deposit_sen, created_by)
57	     values ($1, $2, $3, $4::date, $5::date, $6, $7, $8) returning id`,
58	    [fx.orgId, fx.unitIds[0], fx.tenantAId, lease.startDate, lease.endDate, lease.monthlyRentSen, lease.depositSen, fx.users.manager.userId],
59	  );
60	  const leaseId = rows[0].id;
61	  const order = rentFirst
62	    ? [...schedule.filter((i) => i.kind === "rent"), ...schedule.filter((i) => i.kind === "deposit")]
63	    : schedule;
64	  const ids = new Map<ScheduledInvoice, string>();
65	  for (const inv of order) {
