5	// D3: the one place a Prisma BigInt (bigint sen column) becomes a JS number; refuses unsafe values.
6	export function toSen(v: bigint | number): number {
7	  if (typeof v === 'bigint') {
8	    if (v > BigInt(Number.MAX_SAFE_INTEGER) || v < BigInt(Number.MIN_SAFE_INTEGER)) {
9	      throw new Error('Amount is outside the safe integer range')
