18	export function formatSen(sen: number): string {
19	  const value = toSen(sen)
20	  const abs = Math.abs(value)
21	  const ringgit = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
22	  const cents = String(abs % 100).padStart(2, '0')
23	  return `${value < 0 ? '-' : ''}RM ${ringgit}.${cents}`
24	}
