1	import pg from "pg";
2	import { env } from "./env";
3	
4	// Direct Postgres access as the `postgres` owner (DATABASE_URL). For fixtures, catalog checks
5	// (information_schema / pg_catalog) and asserting DB state. Never used to reset the DB.
6	
7	// Per-connection type parsers (never the global pg.types, which Prisma's adapter-pg also uses):
8	// int8 -> number when it is a safe integer (money is bigint sen, D3); date -> raw "YYYY-MM-DD"
9	// string, never a local-time Date (TZ-independent).
10	const INT8 = 20;
11	const DATE = 1082;
12	const types: pg.CustomTypesConfig = {
13	  getTypeParser: ((oid: number, format?: "text" | "binary") => {
14	    if (oid === INT8)
15	      return (v: string) => {
16	        const n = Number(v);
17	        if (!Number.isSafeInteger(n)) throw new Error(`int8 ${v} is not a safe integer`);
18	        return n;
19	      };
20	    if (oid === DATE) return (v: string) => v;
21	    return pg.types.getTypeParser(oid, format ?? "text");
22	  }) as pg.CustomTypesConfig["getTypeParser"],
23	};
24	
25	let shared: pg.Pool | undefined;
26	
27	/** Shared pool for the current test file (max 5). Call closePool() in afterAll. */
28	export function pool(): pg.Pool {
29	  shared ??= new pg.Pool({ connectionString: env.databaseUrl, max: 5, types });
30	  return shared;
31	}
32	
33	/** Run one parameterized query on the shared pool and return its rows. */
34	export async function sql<T extends pg.QueryResultRow = pg.QueryResultRow>(
35	  text: string,
36	  params: unknown[] = [],
37	): Promise<T[]> {
38	  const res = await pool().query<T>(text, params);
39	  return res.rows;
40	}
